<?php $t=$tour??[]; $v=fn($f,$d='')=>old($f,$t[$f]??$d); ?><div class="card form-card"><div class="form-section-title">Tour Package</div><div class="form-grid"><div class="form-group"><label>Product *</label><select name="product_id" required><option value="">-- Select Tour Product --</option><?php foreach($products as $p): ?><option value="<?=$p['id']?>" <?=$v('product_id')==$p['id']?'selected':''?>><?=esc($p['name'])?> — <?=esc($p['product_code'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Package Code *</label><input name="package_code" value="<?=esc($v('package_code'))?>" required placeholder="TOUR-BDG-3D2N"></div><div class="form-group full"><label>Tour Name *</label><input name="name" value="<?=esc($v('name'))?>" required></div><div class="form-group"><label>Destination *</label><input name="destination" value="<?=esc($v('destination'))?>" required></div><div class="form-group"><label>Duration Days *</label><input type="number" min="1" name="duration_days" value="<?=esc($v('duration_days',1))?>" required></div><div class="form-group"><label>Duration Nights *</label><input type="number" min="0" name="duration_nights" value="<?=esc($v('duration_nights',0))?>" required></div><div class="form-group"><label class="checkbox-label"><input type="checkbox" name="is_active" value="1" <?=$v('is_active',1)?'checked':''?>> Active package</label></div><div class="form-group full"><label>Description</label><textarea name="description" rows="4"><?=esc($v('description'))?></textarea></div></div><div class="form-actions"><a class="btn btn-secondary" href="<?=site_url('tours')?>">Cancel</a><button class="btn btn-primary"><?=!empty($t['id'])?'Save Changes':'Create Tour'?></button></div></div>